import { UseQueryResult, useQuery } from '@tanstack/react-query'
import { Currency, CurrencyAmount, Token } from '@uniswap/sdk-core'
import { useAccountMeta } from 'uniswap/src/contexts/UniswapContext'
import { useMemo } from 'react'
import { UseQueryApiHelperHookArgs } from 'uniswap/src/data/apiClients/types'
import { CheckApprovalLPRequest, CheckApprovalLPResponse } from 'uniswap/src/data/tradingApi/__generated__'
import { isAbstractChain, getAbstractContracts } from 'uniswap/src/constants/abstractContracts'
import { getAbstractTokenList } from 'uniswap/src/constants/tokens'
import { UniverseChainId } from 'uniswap/src/features/chains/types'
import { ReactQueryCacheKey } from 'utilities/src/reactQuery/cache'
import { useReadContracts } from 'wagmi'
import { Address } from 'viem'
import { ethers } from 'ethers'

// ERC20 ABI for allowance function
const ERC20_ABI = [
  {
    name: 'allowance',
    type: 'function',
    stateMutability: 'view',
    inputs: [
      { name: 'owner', type: 'address' },
      { name: 'spender', type: 'address' }
    ],
    outputs: [{ name: '', type: 'uint256' }]
  },
  {
    name: 'approve',
    type: 'function',
    stateMutability: 'nonpayable',
    inputs: [
      { name: 'spender', type: 'address' },
      { name: 'amount', type: 'uint256' }
    ],
    outputs: [{ name: '', type: 'bool' }]
  }
] as const

interface AbstractLpApprovalParams {
  token0?: Currency
  token1?: Currency
  amount0?: CurrencyAmount<Currency>
  amount1?: CurrencyAmount<Currency>
  chainId: UniverseChainId
  protocolVersion?: 'V2' | 'V3'
}

export function useAbstractLpApprovalQuery({
  params,
  ...rest
}: UseQueryApiHelperHookArgs<CheckApprovalLPRequest, CheckApprovalLPResponse> & {
  headers?: Record<string, string>
}): UseQueryResult<CheckApprovalLPResponse> {
  const account = useAccountMeta()
  const address = account?.address
  
  // Extract Abstract-specific params from the request
  const abstractParams: AbstractLpApprovalParams | null = useMemo(() => {
    if (!params) return null
    
    try {
      const chainId = params.chainId as UniverseChainId
      
      // LP Approval request has different structure than LP Creation request
      const token0Address = params.token0  // Direct property, not nested
      const token1Address = params.token1  // Direct property, not nested
      
      // Detect protocol version from the explicit protocol field
      const protocolVersion = (params as any).protocol === 'V3' ? 'V3' : 'V2'
      
      // Get token info from our Abstract token list to get correct decimals
      const abstractTokens = getAbstractTokenList(chainId)
      const token0Data = abstractTokens.find(t => t.address.toLowerCase() === token0Address?.toLowerCase())
      const token1Data = abstractTokens.find(t => t.address.toLowerCase() === token1Address?.toLowerCase())
      
      // Create Currency objects with correct decimals
      const token0 = token0Data || (token0Address ? new Token(chainId, token0Address, 18) : undefined)
      const token1 = token1Data || (token1Address ? new Token(chainId, token1Address, 18) : undefined)
      
      // Amounts are direct properties in approval request
      const amount0Raw = params.amount0
      const amount1Raw = params.amount1
      
      const amount0 = token0 && amount0Raw ? CurrencyAmount.fromRawAmount(token0, amount0Raw) : undefined
      const amount1 = token1 && amount1Raw ? CurrencyAmount.fromRawAmount(token1, amount1Raw) : undefined

      return {
        chainId,
        token0,
        token1,
        amount0,
        amount1,
        protocolVersion,
      }
    } catch (error) {
      console.warn('Failed to extract tokens from LP approval params:', error)
      return null
    }
  }, [params])

  const contracts = getAbstractContracts(abstractParams?.chainId || UniverseChainId.Sepolia)
  const routerAddress = contracts?.router
  const nftManagerAddress = contracts?.nonfungiblePositionManager

  // Build multicall contracts array
  const multicallContracts = useMemo(() => {
    if (!abstractParams || !address) return []

    const contractCalls = []

    // For V2: Check router allowances
    if (abstractParams.protocolVersion === 'V2' && routerAddress) {
      if (abstractParams.token0?.isToken) {
        contractCalls.push({
          address: abstractParams.token0.address as Address,
          abi: ERC20_ABI,
          functionName: 'allowance',
          args: [address as Address, routerAddress as Address]
        })
      }
      if (abstractParams.token1?.isToken) {
        contractCalls.push({
          address: abstractParams.token1.address as Address,
          abi: ERC20_ABI,
          functionName: 'allowance',
          args: [address as Address, routerAddress as Address]
        })
      }
    }

    // For V3: Check NFT manager allowances
    if (abstractParams.protocolVersion === 'V3' && nftManagerAddress) {
      if (abstractParams.token0?.isToken) {
        contractCalls.push({
          address: abstractParams.token0.address as Address,
          abi: ERC20_ABI,
          functionName: 'allowance',
          args: [address as Address, nftManagerAddress as Address]
        })
      }
      if (abstractParams.token1?.isToken) {
        contractCalls.push({
          address: abstractParams.token1.address as Address,
          abi: ERC20_ABI,
          functionName: 'allowance',
          args: [address as Address, nftManagerAddress as Address]
        })
      }
    }

    return contractCalls
  }, [abstractParams, address, routerAddress, nftManagerAddress])


  // Single multicall for all allowances
  const { data: allowanceResults, isLoading, isError, error, refetch } = useReadContracts({
    contracts: multicallContracts,
    query: {
      enabled: Boolean(
        abstractParams && 
        address && 
        isAbstractChain(abstractParams.chainId) &&
        multicallContracts.length > 0
      ),
      refetchInterval: 10000, // Refetch every 10 seconds
    }
  })



  const queryKey = [ReactQueryCacheKey.AbstractLpApproval, abstractParams, address]

  return useQuery<CheckApprovalLPResponse>({
    queryKey: [...queryKey, allowanceResults?.map(r => r.result?.toString()).join(',')],
    enabled: Boolean(abstractParams && address && allowanceResults && !isLoading),
    queryFn: async () => {
      // The enabled condition ensures these are all available
      if (!abstractParams || !address || !allowanceResults) {
        throw new Error('Invalid parameters for Abstract LP approval - should not happen due to enabled condition')
      }


      const response: CheckApprovalLPResponse = {
        token0Approval: null,
        token1Approval: null,
        token0Cancel: null,
        token1Cancel: null,
        token0PermitTransaction: null,
        token1PermitTransaction: null,
        gasFeeToken0Approval: null,
        gasFeeToken1Approval: null,
        gasFeeToken0Permit: null,
        gasFeeToken1Permit: null,
      }

      // Parse allowance results based on protocol version
      let token0Allowance: bigint = 0n
      let token1Allowance: bigint = 0n

      if (abstractParams.protocolVersion === 'V2') {
        // V2: Results are [token0RouterAllowance, token1RouterAllowance]
        let resultIndex = 0
        if (abstractParams.token0?.isToken && allowanceResults[resultIndex]) {
          token0Allowance = allowanceResults[resultIndex].status === 'success' ? 
            BigInt(allowanceResults[resultIndex].result?.toString() || '0') : 0n
          resultIndex++
        }
        if (abstractParams.token1?.isToken && allowanceResults[resultIndex]) {
          token1Allowance = allowanceResults[resultIndex].status === 'success' ? 
            BigInt(allowanceResults[resultIndex].result?.toString() || '0') : 0n
        }
      } else {
        // V3: Results are [token0NftAllowance, token1NftAllowance]
        let resultIndex = 0
        if (abstractParams.token0?.isToken && allowanceResults[resultIndex]) {
          token0Allowance = allowanceResults[resultIndex].status === 'success' ? 
            BigInt(allowanceResults[resultIndex].result?.toString() || '0') : 0n
          resultIndex++
        }
        if (abstractParams.token1?.isToken && allowanceResults[resultIndex]) {
          token1Allowance = allowanceResults[resultIndex].status === 'success' ? 
            BigInt(allowanceResults[resultIndex].result?.toString() || '0') : 0n
        }
      }

      // Check if approvals are needed and create approval transactions
      const spenderAddress = abstractParams.protocolVersion === 'V2' ? routerAddress : nftManagerAddress
      // Always approve max amount to avoid multiple approvals
      const MAX_UINT256 = '0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff'

      if (abstractParams.token0?.isToken && abstractParams.amount0 && spenderAddress) {
        const amount0Needed = BigInt(abstractParams.amount0.quotient.toString())
        if (token0Allowance < amount0Needed) {
          response.token0Approval = {
            to: abstractParams.token0.address,
            data: new ethers.utils.Interface(ERC20_ABI).encodeFunctionData('approve', [
              spenderAddress,
              MAX_UINT256 // Approve maximum amount to avoid repeated approvals
            ]),
            value: '0',
            from: address,
            chainId: abstractParams.chainId,
          }
          response.gasFeeToken0Approval = '50000000000000' // 50k gas * 1 gwei
        }
      }

      if (abstractParams.token1?.isToken && abstractParams.amount1 && spenderAddress) {
        const amount1Needed = BigInt(abstractParams.amount1.quotient.toString())
        if (token1Allowance < amount1Needed) {
          response.token1Approval = {
            to: abstractParams.token1.address,
            data: new ethers.utils.Interface(ERC20_ABI).encodeFunctionData('approve', [
              spenderAddress,
              MAX_UINT256 // Approve maximum amount to avoid repeated approvals
            ]),
            value: '0',
            from: address,
            chainId: abstractParams.chainId,
          }
          response.gasFeeToken1Approval = '50000000000000' // 50k gas * 1 gwei
        }
      }

      return response
    },
    ...rest,
  })
}
