import { UniverseChainId } from 'uniswap/src/features/chains/types'

export interface PoolInfo {
  address: string
  exists: boolean
  sqrtPriceX96: string
  tick: number
  tickSpacing: number
}

export interface AbstractLpRequest {
  token0: string
  token1: string
  amount0: string
  amount1: string
  chainId: UniverseChainId
  protocolVersion: 'V2' | 'V3'
  slippageTolerance: number
  deadline: number
  
  // V2 specific
  stable?: boolean
  
  // V3 specific  
  tickLower?: number
  tickUpper?: number
  fee?: number
  tickSpacing?: number
  createPool?: boolean
  tokenId?: string // For increase liquidity
}

export interface ProcessedTokens {
  finalToken0: string
  finalToken1: string
  finalAmount0: string
  finalAmount1: string
  finalAmount0Min: string
  finalAmount1Min: string
  isToken0OriginallyETH: boolean
  isToken1OriginallyETH: boolean
}

export interface TransactionCalldata {
  to: string
  data: string
  value: string
  from: string
  chainId: UniverseChainId
}

export interface V3MintParams {
  token0: string
  token1: string
  tickSpacing: number
  tickLower: number
  tickUpper: number
  amount0Desired: string
  amount1Desired: string
  amount0Min: string
  amount1Min: string
  recipient: string
  deadline: number
  sqrtPriceX96: string
}

export interface PoolCreationParams {
  token0: string
  token1: string
  tickSpacing: number
  sqrtPriceX96: string
}

// Mapping fee amounts to tick spacings for Abstract DEX
export const ABSTRACT_TICK_SPACINGS: { [key: number]: number } = {
  100: 1,     // 0.01% -> tick spacing 1
  500: 100,   // 0.05% -> tick spacing 100  
  3000: 200,  // 0.3% -> tick spacing 200
  10000: 2000 // 1% -> tick spacing 2000
}